with enriched as (select id, channel, promo_code, starts_on, ends_on, sum(discount_pct) over (partition by promo_code order by starts_on, id rows between unbounded preceding and current row) as cumulative_discount_pct, lag(discount_pct, 1) over w_grp as prev_discount_pct, lag(discount_pct, 1) over (partition by date_trunc('month', ends_on), promo_code order by discount_pct, id) as prev_discount_pct_2 from promotions window w_grp as (order by discount_pct, id)), kept_keys as (select id from enriched except all select id from promotions where starts_on > '2024-10-01'), kept_rows as (select s.* from enriched s join kept_keys k on s.id = k.id), with_window as (select a.*, pr.id as promo_id, pr.promo_code as promotion_promo_code, pr.discount_pct from kept_rows a left join promotions pr on a.channel = pr.channel and a.starts_on >= pr.starts_on and a.starts_on < pr.ends_on + interval '14' day), metrics as (select channel, promo_code, starts_on, ends_on, cumulative_discount_pct, prev_discount_pct, discount_pct, count(cumulative_discount_pct) over (partition by promotion_promo_code) as promotion_promo_code_count_cumulative_discount_pct, dense_rank() over (order by discount_pct desc nulls first) as discount_pct_dense_rank, percent_rank() over (order by prev_discount_pct nulls last) as prev_discount_pct_percent_rank, percent_rank() over (order by discount_pct desc nulls last) as discount_pct_percent_rank, dense_rank() over (order by discount_pct desc) as discount_pct_dense_rank_2 from with_window where prev_discount_pct_2 <= 0.17), with_window_promotions as (select e.*, pr.id as promo_id, pr.promo_code as promotion_promo_code, pr.discount_pct as promotion_discount_pct from metrics e join promotions pr on coalesce(e.channel, 'store') = pr.channel and e.ends_on >= pr.starts_on and e.ends_on < pr.ends_on + interval '7' day) select promo_code, ends_on, cumulative_discount_pct, discount_pct, promotion_promo_code_count_cumulative_discount_pct, discount_pct_dense_rank, discount_pct_percent_rank, promo_id, promotion_promo_code from with_window_promotions order by cumulative_discount_pct desc nulls first;
